function normalizeLon(lon       ){return ((lon+180)%360+360)%360-180}
function meanMotion(altitude       ){return Math.sqrt(MU/Math.pow(R+altitude,3))}
// Synthetic circular orbit in a simplified rotating spherical Earth frame. NOT TLE/SGP4.
