function stationLink(p         ,station        ){const a=ecef(station.position),b=ecef(p),v=b.map((n,i)=>n-a[i]),distance=Math.hypot(...v),length=Math.hypot(...a);const elevation=deg(Math.asin(Math.max(-1,Math.min(1,v.reduce((s,n,i)=>s+n*a[i]/length,0)/distance))));const lon=rad(station.position.lon),lat=rad(station.position.lat);const east=-Math.sin(lon)*v[0]+Math.cos(lon)*v[1],north=-Math.sin(lat)*Math.cos(lon)*v[0]-Math.sin(lat)*Math.sin(lon)*v[1]+Math.cos(lat)*v[2];return {distance,elevation,azimuth:(deg(Math.atan2(east,north))+360)%360,visible:elevation>=station.minimumElevation}}
