function windowStatus(w                  ,t       ){return t<w.start?'待执行':t>w.end?'已完成':'观测中'}
function planConflicts(windows                    ,plans       ){return windows.some(w=>plans.some(p=>p.status!=='cancelled'&&p.windows.some(v=>w.satelliteId===v.satelliteId&&w.start<v.end&&v.start<w.end)))}
