const defaultExport = defineComponent({name:'CoverageChart',setup(){const s=useMissionStore(),container=ref                  (null),ready=ref(false);let chart                  ,observer                         ,disposed=false;function render(){chart?.setOption({animation:false,grid:{left:25,right:8,top:8,bottom:21},tooltip:{trigger:'axis',valueFormatter:(value       )=>value+'%'},xAxis:{type:'category',data:s.windows.slice(0,6).map(w=>w.satelliteId),axisLabel:{color:'#73899d',fontSize:8},axisLine:{lineStyle:{color:'#334555'}},axisTick:{show:false}},yAxis:{type:'value',min:0,max:100,interval:50,axisLabel:{color:'#60778b',fontSize:8},splitLine:{lineStyle:{color:'#293c4a'}}},series:[{type:'bar',barMaxWidth:14,data:s.windows.slice(0,6).map(w=>({value:w.coverage,itemStyle:{color:w.eligible?'#cca56f':'#52677b',borderRadius:[2,2,0,0]}})),markLine:{silent:true,symbol:'none',label:{show:false},lineStyle:{color:'#85cdb7',width:1},data:[{yAxis:s.constraints.minCoverage}]}}]})}onMounted(async()=>{try{await loadChart();if(disposed||!container.value)return;chart=(window                                           ).echarts.init(container.value);ready.value=true;render();observer=new ResizeObserver(()=>chart?.resize());observer.observe(container.value)}catch{/* Accessible fallback bars remain usable if optional chart library cannot load. */}});watch(()=>[s.windows,s.constraints.minCoverage],render);onBeforeUnmount(()=>{disposed=true;observer?.disconnect();chart?.dispose()});return {s,container,ready}},template:`<div class="coverage-chart"><div class="chart-label">候选覆盖对比 <span>绿线为覆盖阈值</span></div><div ref="container" class="chart-canvas" role="img" aria-label="候选卫星区域覆盖率对比图"></div><div class="chart-fallback" v-if="!ready"><div v-for="w in s.windows.slice(0,4)" :key="w.id"><span>{{w.satelliteId}}</span><progress :value="w.coverage" max="100"></progress><b>{{w.coverage}}%</b></div></div></div>`});

return {default:defaultExport};
