const {timeLabel} = modules["format.js"];
const {orbitPosition,speedKmS,stationLink} = modules["domain/orbit.js"];
const defaultExport = defineComponent({name:'PlanningPanel',components:{CoverageChart},emits:['preview','track','locate'],setup(_,ctx){const s=useMissionStore();const telemetry=computed(()=>s.satellite?{...orbitPosition(s.satellite.orbit,s.seconds),speed:speedKmS(s.satellite.orbit)}:null);const links=computed(()=>s.data&&telemetry.value?s.data.stations.map(st=>({name:st.name,...stationLink(telemetry.value ,st)})):[]);const nextWindow=computed(()=>s.windows.filter(w=>w.satelliteId===s.satelliteId&&w.end>=s.seconds).sort((a,b)=>a.start-b.start)[0]);return {s,timeLabel,telemetry,links,nextWindow,preview:(w        )=>ctx.emit('preview',w),track:()=>ctx.emit('track'),locate:()=>ctx.emit('locate')}},template:`
<aside class="float-panel planning-panel"><div class="panel-tabs"><button :class="{active:s.activePanel==='planning'}" @click="s.activePanel='planning'">观测规划</button><button :class="{active:s.activePanel==='satellite'}" @click="s.activePanel='satellite'">卫星详情</button></div>
<template v-if="s.activePanel==='planning'"><div class="plan-heading"><div class="tiny-title">覆盖评估 <span>网格采样估算</span></div><div class="coverage-summary"><div class="coverage-dial" :style="{'--coverage':s.coverage+'%'}"><div><b>{{s.coverage}}</b><small>%</small></div></div><div><strong>{{s.selectedWindows.length}} 个窗口已选</strong><p>目标区域联合覆盖</p><span class="green">{{s.eligibleCount}} 个窗口满足约束</span></div></div></div>
<div class="constraints"><div class="tiny-title">规划约束</div><div class="constraint-inputs"><label>载荷<select v-model="s.constraints.sensor" @change="s.autoSelect"><option value="ALL">全部载荷</option><option value="SAR">SAR 雷达</option><option value="OPT">光学</option></select></label><label>最低覆盖<select v-model.number="s.constraints.minCoverage" @change="s.autoSelect"><option :value="30">30%</option><option :value="60">60%</option><option :value="90">90%</option></select></label></div><label class="cloud-control"><span>光学云量上限 <b>{{s.constraints.maxCloud}}%</b></span><input type="range" min="0" max="100" step="5" v-model.number="s.constraints.maxCloud" @change="s.autoSelect" aria-label="光学云量上限"></label></div>
<CoverageChart/><div class="window-heading"><span>候选窗口</span><small>评分排序 · 演练当日 14–16 时</small></div>
<div class="window-list"><div v-for="w in s.windows" :key="w.id" :class="['window-card',{selected:s.selectedIds.includes(w.id),rejected:!w.eligible}]"><div class="window-top"><label><input type="checkbox" :checked="s.selectedIds.includes(w.id)" :disabled="!w.eligible" @change="s.toggleWindow(w)"><b>{{s.data?.satellites.find(v=>v.id===w.satelliteId)?.name}}</b></label><span>{{w.coverage}}%</span></div><div class="window-time">{{timeLabel(w.start)}} — {{timeLabel(w.end)}}</div><div class="coverage-bar"><i :style="{width:w.coverage+'%'}"></i></div><div class="window-footer"><small>{{w.eligible?'评分 '+w.score+' · 可用':w.reason}}</small><button @click="preview(w)" title="跳转到此窗口并查看条带">预览 ↗</button></div></div><div v-if="!s.windows.length" class="empty">当前载荷在演练时段内没有过境窗口</div></div>
<div class="plan-action"><button class="primary full" :disabled="!s.selectedWindows.length" @click="s.createPlan">＋ 生成观测计划</button><p>仅创建本地演示计划，不下发卫星指令</p></div></template>
<template v-else-if="s.satellite && telemetry"><div class="satellite-title"><div class="sat-icon">✧</div><div><span>{{s.satellite.id}} / SIMULATED</span><h3>{{s.satellite.name}}</h3><small :class="s.satellite.available?'green':'red'">● {{s.satellite.available?'资源可用':'维护中'}}</small></div></div><div class="sat-actions"><button @click="locate">定位卫星 ↗</button><button @click="track">跟踪视角 ◎</button></div><div class="telemetry-grid"><div><span>轨道高度</span><b>{{telemetry.alt.toFixed(0)}} <small>km</small></b></div><div><span>轨道速度</span><b>{{telemetry.speed.toFixed(2)}} <small>km/s</small></b></div><div><span>经度</span><b>{{telemetry.lon.toFixed(2)}}°</b></div><div><span>纬度</span><b>{{telemetry.lat.toFixed(2)}}°</b></div></div><dl class="sat-properties"><div><dt>载荷 / 分辨率</dt><dd>{{s.satellite.sensor}} / {{s.satellite.resolution}} m</dd></div><div><dt>天底覆盖幅宽</dt><dd>{{s.satellite.swathKm}} km</dd></div><div><dt>近似视场角 FOV</dt><dd>{{(2*Math.atan(s.satellite.swathKm/(2*s.satellite.orbit.altitude))*180/Math.PI).toFixed(1)}}°</dd></div><div><dt>轨道倾角</dt><dd>{{s.satellite.orbit.inclination}}°</dd></div><div><dt>NORAD 编号</dt><dd>无 · 虚构卫星</dd></div><div><dt>姿态模型</dt><dd>沿速度方向 · 天底指向</dd></div><div><dt>下一观测窗口</dt><dd>{{nextWindow?timeLabel(nextWindow.start):'本时段无窗口'}}</dd></div></dl><div class="resource-gauges"><label>电量 · 模拟 <b>{{s.satellite.battery}}%</b><progress :value="s.satellite.battery" max="100"></progress></label><label>可用存储 · 模拟 <b>{{s.satellite.storage}}%</b><progress :value="s.satellite.storage" max="100"></progress></label></div><div class="tiny-title station-title">星地可见性 <span>最低仰角 10°</span></div><div class="station-link" v-for="link in links" :key="link.name"><div><span>{{link.name.split(' ·')[0]}}</span><b :class="{green:link.visible}">{{link.visible?'可见':'不可见'}}</b></div><small>仰角 {{link.elevation.toFixed(1)}}° · 方位 {{link.azimuth.toFixed(0)}}° · {{link.distance.toFixed(0)}} km</small></div><p class="panel-footnote">简化圆轨道与球形地球模型；不是实时星历</p></template></aside>`});

