 async function initializeScene(){s.sceneStatus='loading';s.sceneError='';try{await loadCesium();if(disposed||!s.data||!globe.value)return;manager?.destroy();manager=undefined;globe.value.innerHTML='';manager=new SceneManager(globe.value,s.data,{tick:seconds=>{s.seconds=seconds;if(seconds>=7200)s.playing=false},pick:id=>{if(id.startsWith('EV-')){s.setEvent(id);s.activePanel='planning'}else pickSatellite(id)},coordinates:text=>s.mouse=text,error:message=>{s.sceneStatus='error';s.sceneError=message;s.playing=false;manager?.setPlayback(false,s.speed)},imagery:message=>s.imageryStatus=message});manager.select(s.satelliteId);manager.setLayers(s.layers);manager.showWindows(s.selectedWindows,s.layers);manager.setPlans(s.plans);manager.setTime(s.seconds);s.sceneStatus='ready'}catch(e){s.sceneStatus='error';s.sceneError=e instanceof Error?e.message:'无法创建三维场景';s.playing=false}}
